//! The contracts between Trenova's services, as Rust. Generated from
//! `services/proto` at build time; see that directory for the definitions and
//! their documentation. Go code for the same contracts is generated by buf and
//! checked in next to the Go code that consumes it.

#[allow(
    clippy::pedantic,
    clippy::doc_markdown,
    clippy::large_enum_variant,
    clippy::derive_partial_eq_without_eq,
    missing_debug_implementations
)]
pub mod imaging {
    pub mod v1 {
        tonic::include_proto!("trenova.imaging.v1");

        /// The ErrorInfo domain every imaging error carries.
        pub const ERROR_DOMAIN: &str = "imaging.trenova.app";
    }
}
